export function addQualifierToQuery(query: string, qualifier: string, value: string): string {
  const qualifierString = `${qualifier}:${value}`

  if (query === '') {
    return qualifierString
  }

  const filterTerms = query.split(' ').filter(term => term.length > 0)
  const nonQualifierTerms = filterTerms.filter(term => !term.startsWith(`${qualifier}:`))
  if (nonQualifierTerms.length === 0) {
    return qualifierString
  }

  const newQuery = filterTerms.length === nonQualifierTerms.length ? query : nonQualifierTerms.join(' ')
  return `${newQuery} ${qualifierString}`
}

export function removeQualifierFromQuery(query: string, qualifier: string): string {
  if (query === '') {
    return query
  }

  const filterTerms = query.split(' ').filter(term => term.length > 0)
  const nonQualifierTerms = filterTerms.filter(term => !term.startsWith(`${qualifier}:`))
  if (nonQualifierTerms.length === filterTerms.length) {
    return query
  }

  return nonQualifierTerms.join(' ')
}

export function getQualifierFromQuery(query: string, qualifier: string): string[] {
  if (!query) {
    return []
  }

  const terms = query.split(' ').filter(term => term.startsWith(`${qualifier}:`))
  if (terms.length === 0) {
    return []
  }

  return terms.flatMap(term => {
    const value = term.substring(`${qualifier}:`.length)
    return value.split(',').filter(v => v.length > 0)
  })
}
