import {Blankslate} from '@primer/react/experimental'
import {codeQualitySettingsPath} from '@github-ui/paths'
import type {CodeQualityDocsUrls} from '../types/code-quality-docs-urls'

export type RepoCodeQualityDisabledProps = {
  owner: string
  repo: string
  codeQualityDocsUrls: CodeQualityDocsUrls
  readonly?: boolean
  blockedByPolicy?: boolean
}

export function RepoCodeQualityDisabled(props: RepoCodeQualityDisabledProps) {
  const {owner, repo, codeQualityDocsUrls, readonly = false, blockedByPolicy = false} = props
  const showAction = !readonly && !blockedByPolicy
  return (
    <Blankslate border>
      <Blankslate.Heading>Code Quality is not enabled for this repository</Blankslate.Heading>
      <Blankslate.Description>
        <Description readonly={readonly} blockedByPolicy={blockedByPolicy} />
      </Blankslate.Description>
      {showAction ? (
        <Blankslate.PrimaryAction href={codeQualitySettingsPath({owner, repo})}>
          Enable Code Quality
        </Blankslate.PrimaryAction>
      ) : null}
      <Blankslate.SecondaryAction href={codeQualityDocsUrls.about}>
        Learn more about Code Quality
      </Blankslate.SecondaryAction>
    </Blankslate>
  )
}

const Description = ({readonly, blockedByPolicy}: {readonly: boolean; blockedByPolicy: boolean}) => {
  if (readonly) {
    return (
      <span data-testid="disabled-readonly-blankslate">
        Please contact a repository administrator to enable Code Quality.
      </span>
    )
  } else if (blockedByPolicy) {
    return (
      <span data-testid="disabled-blocked-by-policy-blankslate">
        Code Quality has been disabled for this repository by your organization&apos;s policies. Please contact your
        administrator for more information.
      </span>
    )
  } else {
    return (
      <span data-testid="disabled-enableable-blankslate">
        Enable Code Quality to start identifying and fixing code quality issues in your repository.
      </span>
    )
  }
}
