import {Blankslate} from '@primer/react/experimental'
import {CodeSquareIcon} from '@primer/octicons-react'
import {Heading, Link, Stack} from '@primer/react'

import {BetaLabel} from '@github-ui/lifecycle-labels/beta'
import DataCard from '@github-ui/data-card'
import {codeQualityAIFindingsPath} from '@github-ui/paths'

import {Metric} from './Metric'
import {RecentSuggestionsCard} from './RecentSuggestionsCard'
import styles from './RecentSuggestionsCard.module.css'
import type {CodeQualityDocsUrls} from '../types/code-quality-docs-urls'

import {Grade} from '../types/grade'
import {RuleList} from './RuleList'

export type RepoCodeQualityEnabledProps = {
  owner: string
  repo: string
  branch: string
  lastScanAt: string | null
  maintainability: {
    grade: Grade
    findingsCount: number
  }
  reliability: {
    grade: Grade
    findingsCount: number
  }
  recentActivityEnabled: boolean
  recentSuggestionsCount: number
  codeQualityDocsUrls: CodeQualityDocsUrls
}

export function RepoCodeQualityEnabled(props: RepoCodeQualityEnabledProps) {
  const {
    owner,
    repo,
    branch,
    lastScanAt,
    maintainability,
    reliability,
    recentActivityEnabled,
    recentSuggestionsCount,
    codeQualityDocsUrls,
  } = props

  const totalFindings = maintainability.findingsCount + reliability.findingsCount
  const hasScanData = lastScanAt !== null

  const maintainabilityData = hasScanData && totalFindings === 0 ? {grade: Grade.A, findingsCount: 0} : maintainability
  const reliabilityData = hasScanData && totalFindings === 0 ? {grade: Grade.A, findingsCount: 0} : reliability
  return (
    <>
      <div className="d-flex flex-items-center flex-justify-between flex-wrap mb-1" data-testid="code-quality-findings">
        <div className="d-flex flex-items-center gap-2">
          <Heading className="h3" as="h2">
            Standard findings
          </Heading>
          <BetaLabel />
        </div>
      </div>
      <p className="fgColor-muted">
        View findings from a full CodeQL scan of your codebase and improve your code quality scores.
        {recentActivityEnabled && (
          <>
            {' '}
            To see code quality findings from AI in your most recently changed files go to{' '}
            <Link href={codeQualityAIFindingsPath({owner, repo})} inline>
              AI findings
            </Link>
            .
          </>
        )}
      </p>
      <Stack
        direction={{narrow: 'vertical', regular: 'horizontal'}}
        gap="normal"
        className="pt-1 tmp-mb-4"
        wrap="wrap"
        column-fill="balance"
      >
        <Metric
          title="Maintainability"
          data={hasScanData ? maintainabilityData : undefined}
          codeQualityDocsUrls={codeQualityDocsUrls}
        />
        <Metric
          title="Reliability"
          data={hasScanData ? reliabilityData : undefined}
          codeQualityDocsUrls={codeQualityDocsUrls}
        />
        {recentActivityEnabled ? (
          <RecentSuggestionsCard owner={owner} repo={repo} count={recentSuggestionsCount} />
        ) : (
          <DataCard className={styles.Card}>
            <h3 className={styles.Heading}>Total findings</h3>
            <p className={styles.Count}>{hasScanData ? totalFindings : 'No data'}</p>
          </DataCard>
        )}
      </Stack>
      {totalFindings > 0 ? (
        <RuleList owner={owner} repo={repo} branch={branch} />
      ) : (
        <Blankslate className="border rounded-2">
          <Blankslate.Visual>
            <CodeSquareIcon className="mb-2" size="medium" />
          </Blankslate.Visual>
          <Blankslate.Heading>{hasScanData ? 'No open findings' : 'No findings available'}</Blankslate.Heading>
          <Blankslate.Description>
            {hasScanData ? (
              <>No findings detected in the last full CodeQL scan.</>
            ) : (
              <>This repository doesn&apos;t have code quality findings yet. Please come back later.</>
            )}
          </Blankslate.Description>
          {hasScanData && recentActivityEnabled && (
            <Blankslate.Description className="mt-2 text-center">
              To view and fix findings detected by AI in your most recently changed files go to{' '}
              <Link
                href={codeQualityAIFindingsPath({
                  owner,
                  repo,
                })}
                inline
              >
                AI findings
              </Link>
              .
            </Blankslate.Description>
          )}
        </Blankslate>
      )}
    </>
  )
}
