import type {SuggestedFixDiffLine} from '../../types/suggested-fix'

export function groupDiffLines(lines: SuggestedFixDiffLine[]): {
  leftLines: Array<SuggestedFixDiffLine | null>
  rightLines: Array<SuggestedFixDiffLine | null>
} {
  const leftLines: Array<SuggestedFixDiffLine | null> = []
  const rightLines: Array<SuggestedFixDiffLine | null> = []

  // Keep list of lines even, filling in blanks as needed
  const fillBlanks = () => {
    while (leftLines.length < rightLines.length) {
      leftLines.push(null)
    }

    while (rightLines.length < leftLines.length) {
      rightLines.push(null)
    }
  }

  for (const line of lines) {
    switch (line.type) {
      case 'ADDITION':
        rightLines.push(line)
        break
      case 'DELETION':
        leftLines.push(line)
        break
      case 'CONTEXT':
      case 'INJECTED_CONTEXT':
        fillBlanks()
        leftLines.push(line)
        rightLines.push(line)
        break
      case 'HUNK':
        fillBlanks()
        leftLines.push(line)
        rightLines.push(line)
    }
  }
  fillBlanks()

  return {leftLines, rightLines}
}
