import {FindingState} from '../types/rule-finding'

export function getFilteredFindingsCount(
  openCount: number,
  dismissedCount: number,
  activeStates: FindingState[],
): number {
  const hasOpen = activeStates.includes(FindingState.Open)
  const hasDismissed = activeStates.includes(FindingState.Dismissed)

  if ((hasOpen && hasDismissed) || (!hasOpen && !hasDismissed)) {
    return openCount + dismissedCount
  }

  return hasDismissed ? dismissedCount : openCount
}
