import {codeQualityRulesPath} from '@github-ui/paths'
import {RowsLoading} from './RowsLoading'
import {ErrorState} from './ErrorState'
import {ListView} from '@github-ui/list-view'
import {ListViewMetadata} from '@github-ui/list-view/ListViewMetadata'
import {BlankslateListItem} from './BlankslateListItem'
import {Blankslate} from '@primer/react/experimental'
import {PrevNextPagination} from '@github-ui/code-scanning-shared/components/PrevNextPagination'
import {useRulesQuery} from '../hooks/use-rules-query'
import {useFilterParams} from '../hooks/use-filter-params'
import {useSortParams} from '../hooks/use-sort-params'
import type {Rule} from '../types/rule'
import {RuleListItem} from './RuleListItem'
import pluralize from 'pluralize'
import {number as formatNumber} from '@github-ui/formatters'
import {RuleListFilter, DEFAULT_QUERY} from './RuleListFilter'
import {RuleSortMenu} from './RuleSortMenu'
import {getActiveStatesFromQuery} from '../utils/get-active-states-from-query'

export interface RuleListProps {
  owner: string
  repo: string
  branch: string
}

export function RuleList({owner, repo, branch}: RuleListProps) {
  const {cursor, query, onCursorChange, onQueryChange} = useFilterParams()
  const {sortField, sortDirection, onSortFieldChange, onSortDirectionChange} = useSortParams()
  const effectiveQuery = query || DEFAULT_QUERY
  const activeStates = getActiveStatesFromQuery(effectiveQuery)
  const rulesPath = codeQualityRulesPath({owner, repo, query: effectiveQuery, sortField, sortDirection})
  const {data, isPending, isError} = useRulesQuery(rulesPath, {cursor})

  const filter = (
    <div className="tmp-mb-3">
      <RuleListFilter query={effectiveQuery} onQueryChange={onQueryChange} />
    </div>
  )

  if (isPending) {
    return (
      <>
        {filter}
        <div className="border rounded-2" data-testid="rules-loading">
          <RowsLoading rowCount={5} />
        </div>
      </>
    )
  }
  if (isError) {
    return (
      <>
        {filter}
        <ErrorState message="Code quality data could not be loaded right now." />
      </>
    )
  }

  const rules = data?.rules || []
  const ruleCount = data?.count || 0
  const listTitle = `${formatNumber(ruleCount)} ${pluralize('rule', ruleCount)}`

  const lastScan = data?.lastScan

  if (ruleCount > 0 && !lastScan) {
    return <ErrorState message="Code quality data could not be loaded right now." />
  }

  return (
    <>
      {filter}
      <div className="mb-2">
        <ListView
          title={listTitle}
          titleHeaderTag="h3"
          metadata={
            <ListViewMetadata title={listTitle}>
              <RuleSortMenu
                sortField={sortField}
                sortDirection={sortDirection}
                onSortFieldChange={onSortFieldChange}
                onSortDirectionChange={onSortDirectionChange}
              />
            </ListViewMetadata>
          }
          className="border rounded-2"
        >
          {ruleCount === 0 && (
            <BlankslateListItem className="rounded-2">
              <Blankslate.Heading>No findings available.</Blankslate.Heading>
              <Blankslate.Description>
                The last scan doesn&apos;t have code quality findings that match your filter criteria.
              </Blankslate.Description>
            </BlankslateListItem>
          )}
          {ruleCount > 0 &&
            lastScan &&
            rules.map((rule: Rule) => (
              <RuleListItem
                key={rule.ruleId}
                rule={rule}
                owner={owner}
                repo={repo}
                branch={branch}
                lastScan={lastScan}
                activeStates={activeStates}
              />
            ))}
        </ListView>
      </div>
      <PrevNextPagination onCursorChange={onCursorChange} prevCursor={data?.prevCursor} nextCursor={data?.nextCursor} />
    </>
  )
}
