import {Banner, Link} from '@primer/react'
import {pullRequestPath} from '@github-ui/paths'
import pluralize from 'pluralize'
import {useAnalytics} from '@github-ui/use-analytics'
import {useEffect} from 'react'

export type RecentActivityFindingsBannerProps = {
  owner: string
  repo: string
  findingsCount: number
  status: 'success' | 'failed'
  prNumber?: number
  prId?: number
  errorMessage?: string
  onDismiss: () => void
}

export function RecentActivityFindingsPrBanner({
  owner,
  repo,
  findingsCount,
  status,
  prNumber,
  prId,
  errorMessage,
  onDismiss,
}: RecentActivityFindingsBannerProps) {
  const {sendAnalyticsEvent} = useAnalytics()

  useEffect(() => {
    if (status === 'success' && prNumber) {
      sendAnalyticsEvent('code_quality.recent_activity_pr_created', 'RECENT_ACTIVITY_PR_CREATED', {
        category: 'code_quality',
        label: 'recent_activity_pr_created',
        pr_id: prId,
        findingsCount,
      })
    }
  }, [findingsCount, prId, prNumber, sendAnalyticsEvent, status])

  if (status === 'success' && prNumber) {
    const prPath = pullRequestPath({repo: {name: repo, ownerLogin: owner}, number: prNumber})

    return (
      <Banner
        title="PR creation success"
        hideTitle
        aria-label="PR creation success"
        variant="success"
        className="mb-2"
        onDismiss={onDismiss}
      >
        <Banner.Description>
          <span>
            {`${findingsCount} ${pluralize('finding', findingsCount)} successfully assigned to Copilot. `}
            <Link href={prPath} target="_blank">
              View PR
            </Link>
            .
          </span>
        </Banner.Description>
      </Banner>
    )
  }

  if (status === 'failed') {
    return (
      <Banner
        title="PR creation failed"
        hideTitle
        aria-label="PR creation failed"
        variant="critical"
        className="mb-2"
        onDismiss={onDismiss}
      >
        <Banner.Description>
          <span>{`Failed to create PR: ${errorMessage || 'Unknown error'}.`} Please try again.</span>
        </Banner.Description>
      </Banner>
    )
  }
}
