import {useMutation, useQueryClient, type UseMutationResult} from '@github-ui/react-query'
import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {
  enterpriseCodeQualityPoliciesRoute,
  type EnterpriseCodeQualityPoliciesResponse,
} from '../routes/enterprise-code-quality-policies-route'
import {fetchJson} from '../utils/fetch-json'

interface UpdateEnterpriseCodeQualityPoliciesParams {
  enterpriseSlug: string
  repoAdminsCanModifyEnablement: boolean
}

interface UpdateEnterpriseCodeQualityPoliciesResult {
  message: string
  repo_admins_can_modify_enablement: boolean
}

export function useUpdateEnterpriseCodeQualityPoliciesMutation(): UseMutationResult<
  UpdateEnterpriseCodeQualityPoliciesResult,
  Error,
  UpdateEnterpriseCodeQualityPoliciesParams
> {
  const queryClient = useQueryClient()
  const {queryKey} = useRouteQuery(enterpriseCodeQualityPoliciesRoute, 'mainQuery')

  return useMutation({
    mutationFn: async (params: UpdateEnterpriseCodeQualityPoliciesParams) => {
      return fetchJson<UpdateEnterpriseCodeQualityPoliciesResult>(
        `/enterprises/${params.enterpriseSlug}/settings/code_quality_policies/update_code_quality_enablement`,
        {
          method: 'PUT',
          body: {all_repo_admins: params.repoAdminsCanModifyEnablement ? 'allowed' : 'not_allowed'},
        },
      )
    },
    onSuccess: (data: UpdateEnterpriseCodeQualityPoliciesResult) => {
      // Update the query cache with the new value
      queryClient.setQueryData<EnterpriseCodeQualityPoliciesResponse>(queryKey, oldData => {
        if (!oldData) return oldData
        return {
          ...oldData,
          repo_admins_can_modify_enablement: data.repo_admins_can_modify_enablement,
        }
      })
      // Also invalidate to ensure consistency
      queryClient.invalidateQueries({queryKey})
    },
  })
}
