import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {enterpriseCodeQualityPoliciesRoute} from '../routes/enterprise-code-quality-policies-route'
import {useUpdateEnterpriseCodeQualityPoliciesMutation} from './use-update-enterprise-code-quality-policies-mutation'

export function useEnterpriseCodeQualityPolicy() {
  const {data, queryKey} = useRouteQuery(enterpriseCodeQualityPoliciesRoute, 'mainQuery')
  const {enterprise_slug, repo_admins_can_modify_enablement, code_quality_availability} = data

  const mutation = useUpdateEnterpriseCodeQualityPoliciesMutation()

  const handlePolicyChange = (allowed: boolean) => {
    if (allowed === repo_admins_can_modify_enablement) return

    mutation.reset()
    mutation.mutate({
      enterpriseSlug: enterprise_slug,
      repoAdminsCanModifyEnablement: allowed,
    })
  }

  return {
    isAllowed: repo_admins_can_modify_enablement,
    isPending: mutation.isPending,
    isSuccess: mutation.isSuccess,
    isError: mutation.isError,
    error: mutation.error,
    handlePolicyChange,
    enterpriseSlug: enterprise_slug,
    codeQualityAvailability: code_quality_availability,
    queryKey,
  }
}
