import type {ReadOnlyAiFindingsSweAgentJob} from '../types/ai-findings'
import {terminalSweAgentJobStatuses} from '../types/swe-agent-job'
import {RecentActivityFindingsPrBanner} from './RecentActivityFindingsPrBanner'

export type RecentActivityFindingsBannersProps = {
  jobs: readonly ReadOnlyAiFindingsSweAgentJob[]
  owner: string
  repo: string
  onDismiss: (jobId: string) => void
}

export function RecentActivityFindingsPrBanners({jobs, owner, repo, onDismiss}: RecentActivityFindingsBannersProps) {
  return (
    <div>
      {jobs.map(job => {
        // If a PR is present then we can show a success banner
        if (job.pull_request) {
          return (
            <RecentActivityFindingsPrBanner
              key={job.job_id}
              owner={owner}
              repo={repo}
              findingsCount={job.files.reduce((sum, file) => sum + file.findings.length, 0)}
              status="success"
              prNumber={job.pull_request.number}
              prId={job.pull_request.id}
              onDismiss={() => onDismiss(job.job_id)}
            />
          )
        }

        // If we've reached a terminal state without a PR number, show a failure banner
        if (job.status && terminalSweAgentJobStatuses.includes(job.status)) {
          return (
            <RecentActivityFindingsPrBanner
              key={job.job_id}
              owner={owner}
              repo={repo}
              findingsCount={job.files.reduce((sum, file) => sum + file.findings.length, 0)}
              status="failed"
              errorMessage={job.error?.message}
              onDismiss={() => onDismiss(job.job_id)}
            />
          )
        }
      })}
    </div>
  )
}
