import {useLocalStorage} from '@github-ui/use-safe-storage/local-storage'
import {TriangleDownIcon, GitPullRequestIcon, AgentIcon} from '@primer/octicons-react'
import {ActionList, ActionMenu, Button, ButtonGroup, Label, Spinner} from '@primer/react'
import styles from './RecentActivityCommitFixButton.module.css'
import {useEffect} from 'react'

type SelectedActionOption = 'fix-with-copilot' | 'open-pr'

export const RECENT_ACTIVITY_COMMIT_FIX_BUTTON_STORAGE_KEY = 'codeQualityRecentActivityCommitFixButton'

export interface CodeQualityCommitFixButtonProps {
  isPrBeingCreated: boolean
  buttonSize?: 'small' | 'medium'
  setShowCreateBranchDialog: (show: boolean) => void
  onFixWithCopilot?: () => void // If not provided, then the "Assign to Copilot" option will be disabled
  disabled?: boolean
  testId?: string
  isInvisibleVariant?: boolean
}

export function CodeQualityCommitFixButton({
  isPrBeingCreated,
  buttonSize = 'medium',
  setShowCreateBranchDialog,
  onFixWithCopilot,
  disabled,
  testId,
  isInvisibleVariant = false,
}: CodeQualityCommitFixButtonProps) {
  const isFixWithCopilotEnabled = !!onFixWithCopilot
  const [selectedAction, setSelectedAction] = useLocalStorage<SelectedActionOption>(
    RECENT_ACTIVITY_COMMIT_FIX_BUTTON_STORAGE_KEY,
    isFixWithCopilotEnabled ? 'fix-with-copilot' : 'open-pr',
  )

  // Set local storage value to 'open-pr' if "Assign to Copilot" is not enabled
  useEffect(() => {
    if (!isFixWithCopilotEnabled && selectedAction === 'fix-with-copilot') {
      setSelectedAction('open-pr')
    }
  }, [isFixWithCopilotEnabled, selectedAction, setSelectedAction])

  const handleOnClick = () => {
    if (selectedAction === 'fix-with-copilot' && onFixWithCopilot) {
      onFixWithCopilot()
    }
    if (selectedAction === 'open-pr') {
      setShowCreateBranchDialog(true)
    }
  }

  return (
    <ButtonGroup>
      <Button
        onClick={handleOnClick}
        disabled={isPrBeingCreated || disabled}
        leadingVisual={isPrBeingCreated ? <Spinner size="small" /> : undefined}
        size={buttonSize}
        data-testid={testId}
        variant={isInvisibleVariant ? 'invisible' : undefined}
      >
        {selectedAction === 'fix-with-copilot' && <>Assign to Copilot</>}
        {selectedAction === 'open-pr' && <>Open pull request</>}
      </Button>
      <ActionMenu>
        <ActionMenu.Button
          aria-label="More options"
          icon={TriangleDownIcon}
          size={buttonSize}
          variant={isInvisibleVariant ? 'invisible' : undefined}
        />
        <ActionMenu.Overlay width="medium">
          <ActionList selectionVariant="single" className={styles.actionMenu}>
            <ActionList.Item
              onSelect={() => setSelectedAction('fix-with-copilot')}
              selected={selectedAction === 'fix-with-copilot'}
              disabled={!isFixWithCopilotEnabled}
            >
              <ActionList.LeadingVisual>
                <AgentIcon />
              </ActionList.LeadingVisual>
              <span className="no-wrap">
                Assign to Copilot {!isFixWithCopilotEnabled && <Label className="ml-1">Coming soon</Label>}
              </span>
              <ActionList.Description variant="block">
                Delegate these suggestions to Copilot so that it can plan and implement the changes for you.
              </ActionList.Description>
            </ActionList.Item>
            <ActionList.Item onSelect={() => setSelectedAction('open-pr')} selected={selectedAction === 'open-pr'}>
              <ActionList.LeadingVisual>
                <GitPullRequestIcon />
              </ActionList.LeadingVisual>
              Open pull request
              <ActionList.Description variant="block">
                Opens a pull request with the suggested changes.
              </ActionList.Description>
            </ActionList.Item>
          </ActionList>
        </ActionMenu.Overlay>
      </ActionMenu>
    </ButtonGroup>
  )
}
