import {clsx} from 'clsx'
import {Cell} from './Cell'

export type EmptyCellProps = {
  isLeftSide?: boolean
}

export function EmptyCell({isLeftSide}: EmptyCellProps) {
  return (
    <Cell
      className={clsx('empty-diff-line', {
        'border-right': isLeftSide,
      })}
      isLeftSide={isLeftSide}
    />
  )
}
