import {useState, useEffect, useCallback} from 'react'
import {useRecentFindingsQuery} from '../hooks/use-recent-findings-query'
import type {AiFileFindings} from '../types/ai-findings'
import {DotFillIcon, InfoIcon, SyncIcon} from '@primer/octicons-react'
import {Button, Checkbox, FormControl, RelativeTime, Spinner} from '@primer/react'
import {codeQualityAIFindingsListFindingsPath} from '@github-ui/paths'
import styles from './RecentActivityFindings.module.css'
import pluralize from 'pluralize'
import {
  areAiFileFindingsSame,
  getFilesWithNewFindings,
  getAnalyticsFindingsCount,
} from '../utils/ai-findings-comparisons'
import {maxDate} from '../utils/max-date'
import {RecentActivityFindingsFile} from './RecentActivityFindingsFile'
import {RecentActivityFindingsPrBanners} from './RecentActivityFindingsPrBanners'
import {useAiFindingsJobs} from '../hooks/use-ai-findings-jobs'
import {RecentActivityFindingsBlankslate} from './RecentActivityFindingsBlankslate'
import {RecentActivityFindingsCopilotNotEnabledDialog} from './RecentActivityFindingsCopilotNotEnabledDialog'
import {useBannerContext} from '@github-ui/role-assignments/banner-provider'
import {useAnalytics, useClickAnalytics} from '@github-ui/use-analytics'
import type {CodeQualityDocsUrls} from '../types/code-quality-docs-urls'
import {RecentActivityCommitFixButton} from './RecentActivityCommitFixButton'

export type RecentActivityFindingsProps = {
  owner: string
  repo: string
  branch: string
  initialFiles: AiFileFindings[]
  copilotSWEAgentEnabled: boolean
  copilotCodingAgentDocsUrl: string
  codeQualityDocsUrls: CodeQualityDocsUrls
  branchListCacheKey: string
  hasRepoWriteAccess: boolean
  refetchInterval?: number
}

export function RecentActivityFindings({
  owner,
  repo,
  branch,
  initialFiles,
  copilotSWEAgentEnabled,
  copilotCodingAgentDocsUrl,
  codeQualityDocsUrls,
  branchListCacheKey,
  hasRepoWriteAccess,
  refetchInterval = 10_000,
}: RecentActivityFindingsProps) {
  const [files, setFiles] = useState<AiFileFindings[]>(() => sortFilesByPath(initialFiles))
  const [filesWithNewFindings, setFilesWithNewFindings] = useState<string[]>([])
  const [pendingFindings, setPendingFindings] = useState<AiFileFindings[]>([])
  const [selectedFiles, setSelectedFiles] = useState<Set<string>>(() => new Set())
  const [showCopilotNotEnabledDialog, setShowCopilotNotEnabledDialog] = useState(false)

  const findingsPath = codeQualityAIFindingsListFindingsPath({owner, repo})
  const {data: findingsData} = useRecentFindingsQuery(findingsPath, {refetchInterval})
  const selectedCount = selectedFiles.size
  const {showBanner} = useBannerContext()

  const handleError = useCallback(
    (error: Error) => {
      let message = 'Unable to create PR. Please try again.'

      if (error.message && error.message.includes('problem_statement exceeds maximum length')) {
        message = 'Maximum context size exceeded. Try again with fewer findings selected.'
      }

      showBanner({
        message,
        variant: 'critical',
      })
    },
    [showBanner],
  )

  const {jobs, createJob, removeJob, isCreatingPr} = useAiFindingsJobs(owner, repo, branch, {
    onError: handleError,
    refetchInterval,
  })
  const {sendClickAnalyticsEvent} = useClickAnalytics()
  const {sendAnalyticsEvent} = useAnalytics()

  useEffect(() => {
    if (findingsData) {
      if (!areAiFileFindingsSame(files, findingsData.fileFindings)) {
        // eslint-disable-next-line react-hooks/set-state-in-effect
        setPendingFindings(sortFilesByPath(findingsData.fileFindings))
      }
    }
  }, [findingsData, files])

  const fileCount = files.length
  const findingsCount = files.reduce((acc, file) => acc + file.findings.length, 0)

  useEffect(() => {
    if (pendingFindings.length > 0) {
      sendAnalyticsEvent('code_quality.recent_activity_pending_findings', 'RECENT_ACTIVITY_PENDING_FINDINGS', {
        category: 'code_quality',
        label: 'recent_activity_pending_findings',
      })
    }
  }, [pendingFindings, sendAnalyticsEvent])

  function handleRefresh() {
    const {existingFindingsCount, newFindingsCount, deprecatedFindingsCount} = getAnalyticsFindingsCount(
      files,
      pendingFindings,
    )
    sendClickAnalyticsEvent({
      category: 'code_quality',
      action: 'recent_activity_refresh_findings',
      label: 'recent_activity_refresh_findings',
      existingFindingsCount,
      newFindingsCount,
      deprecatedFindingsCount,
    })

    setFilesWithNewFindings(getFilesWithNewFindings(files, pendingFindings))
    setFiles(sortFilesByPath(pendingFindings))
    setPendingFindings([])

    // Clear selections when refreshing
    setSelectedFiles(new Set())
  }

  function handleSelectFile(filePath: string, selected: boolean) {
    setSelectedFiles(prev => {
      const next = new Set(prev)
      if (selected) {
        next.add(filePath)
      } else {
        next.delete(filePath)
      }
      return next
    })
  }

  function handleSelectAll() {
    setSelectedFiles(new Set(files.map(file => file.filePath)))
  }

  function handleSelectNone() {
    setSelectedFiles(new Set())
  }

  function handleFixSelectedWithCopilot() {
    if (!copilotSWEAgentEnabled) {
      setShowCopilotNotEnabledDialog(true)
      return
    }

    sendClickAnalyticsEvent({
      category: 'code_quality',
      action: 'recent_activity_fix_with_copilot',
      label: `recent_activity_fix_with_copilot;org:${owner};repo:${repo}`,
      findingsCount: files
        .filter(file => selectedFiles.has(file.filePath))
        .reduce((acc, file) => acc + file.findings.length, 0),
    })

    const selectedFileFindings = files.filter(file => selectedFiles.has(file.filePath))
    void createJob(selectedFileFindings)
  }

  function handleFixWithCopilot(file: AiFileFindings) {
    sendClickAnalyticsEvent({
      category: 'code_quality',
      action: 'recent_activity_fix_with_copilot',
      label: `recent_activity_fix_with_copilot;org:${owner};repo:${repo}`,
      findingsCount: file.findings.length,
    })

    void createJob([file])
  }

  const isCreatingJobForSelectedFiles = isCreatingPr(Array.from(selectedFiles))

  const pendingLastScanAt = maxDate(pendingFindings.map(file => new Date(file.lastPushAt)))
  return (
    <div>
      <RecentActivityFindingsPrBanners jobs={jobs} owner={owner} repo={repo} onDismiss={removeJob} />
      <div className="d-flex flex-items-center flex-justify-between tmp-pl-3 py-2 gap-2">
        <div className="d-flex flex-items-center gap-3">
          {hasRepoWriteAccess && files.length > 0 && (
            <FormControl>
              <Checkbox
                checked={selectedCount === fileCount && fileCount > 0}
                indeterminate={selectedCount > 0 && selectedCount < fileCount}
                onChange={() => (selectedCount === fileCount ? handleSelectNone() : handleSelectAll())}
              />
              <FormControl.Label visuallyHidden>
                {selectedCount === fileCount ? 'Deselect all files' : 'Select all files'}
              </FormControl.Label>
            </FormControl>
          )}
          <span className={styles.recentFindingsHeading}>
            {findingsCount === 0
              ? '0 findings'
              : `${pluralize('finding', findingsCount, true)} in ${pluralize('file', fileCount, true)}`}
          </span>
        </div>
        <div className="d-flex flex-items-center gap-2">
          {pendingFindings.length > 0 && (
            <div className={styles.recentFindingsIndicator}>
              <DotFillIcon className="fgColor-accent" />
              <span className={styles.recentFindingsText}>
                Found recent findings in this repository <RelativeTime date={pendingLastScanAt} />
              </span>
              <Button variant="invisible" onClick={handleRefresh} leadingVisual={<SyncIcon />} className="ml-2">
                Refresh
              </Button>
            </div>
          )}

          {hasRepoWriteAccess && (
            <>
              {selectedCount < 2 ? (
                <RecentActivityCommitFixButton
                  suggestedFixFiles={files
                    .filter(file => selectedFiles.has(file.filePath))
                    .flatMap(file => file.findings.flatMap(f => f.fixFiles))}
                  owner={owner}
                  repo={repo}
                  defaultBranch={branch}
                  branchListCacheKey={branchListCacheKey}
                  onFixWithCopilot={handleFixSelectedWithCopilot}
                  isPrBeingCreated={isCreatingJobForSelectedFiles}
                  disabled={selectedCount === 0}
                />
              ) : (
                <Button
                  onClick={handleFixSelectedWithCopilot}
                  variant="primary"
                  disabled={selectedCount < 1 || isCreatingJobForSelectedFiles}
                  leadingVisual={isCreatingJobForSelectedFiles ? <Spinner size="small" /> : undefined}
                >
                  Assign selected to Copilot
                </Button>
              )}
            </>
          )}
        </div>
      </div>
      <div className="Box">
        {files.length === 0 && <RecentActivityFindingsBlankslate codeQualityDocsUrls={codeQualityDocsUrls} />}
        {files.map(file => (
          <RecentActivityFindingsFile
            key={file.filePath}
            owner={owner}
            repo={repo}
            branch={branch}
            file={file}
            hasNewFindings={filesWithNewFindings.includes(file.filePath)}
            selected={selectedFiles.has(file.filePath)}
            onSelectionChange={(selected: boolean) => handleSelectFile(file.filePath, selected)}
            onFixWithCopilot={() => handleFixWithCopilot(file)}
            isPrBeingCreated={isCreatingPr([file.filePath])}
            copilotSWEAgentEnabled={copilotSWEAgentEnabled}
            copilotCodingAgentDocsUrl={copilotCodingAgentDocsUrl}
            branchListCacheKey={branchListCacheKey}
            hasRepoWriteAccess={hasRepoWriteAccess}
          />
        ))}
      </div>
      <div className={styles.tip}>
        <div>
          <InfoIcon size={16} className="mr-1" />
          Copilot is powered by AI and may make mistakes. Always verify output.
        </div>
      </div>

      {showCopilotNotEnabledDialog && (
        <RecentActivityFindingsCopilotNotEnabledDialog
          copilotCodingAgentDocsUrl={copilotCodingAgentDocsUrl}
          showFixWithoutCopilotButton={selectedCount <= 1}
          suggestedFixFiles={files
            .filter(file => selectedFiles.has(file.filePath))
            .flatMap(file => file.findings.flatMap(f => f.fixFiles))}
          owner={owner}
          repo={repo}
          branch={branch}
          branchListCacheKey={branchListCacheKey}
          onClose={() => setShowCopilotNotEnabledDialog(false)}
        />
      )}
    </div>
  )
}

function sortFilesByPath(files: AiFileFindings[]): AiFileFindings[] {
  return [...files].sort((a, b) => a.filePath.localeCompare(b.filePath))
}
