import {ActionMenu, ActionList, Heading, Spinner} from '@primer/react'
import {useMutation, useQueryClient} from '@github-ui/react-query'
import {MutationSettledBanner} from '../components/MutationSettledBanner'
import {OrgSelectionList} from '../components/OrgSelectionList'
import {useEnterpriseCodeQualityPolicy} from '../hooks/use-enterprise-code-quality-policy'
import type {CodeQualityAvailability} from './enterprise-code-quality-policies-route'
import {fetchJson} from '../utils/fetch-json'

const AVAILABILITY_OPTIONS: Array<{value: CodeQualityAvailability; label: string; description: string}> = [
  {value: 'all', label: 'Allow for all organizations', description: 'All organizations can enable Code Quality.'},
  {
    value: 'selected',
    label: 'Allow for selected organizations',
    description: 'Only selected organizations can enable Code Quality.',
  },
  {value: 'none', label: 'Not available', description: 'Code Quality is not available for any organizations.'},
]

export function EnterpriseCodeQualityPolicies() {
  const {
    isAllowed,
    isPending,
    isSuccess,
    error,
    handlePolicyChange,
    enterpriseSlug,
    codeQualityAvailability,
    queryKey,
  } = useEnterpriseCodeQualityPolicy()

  const queryClient = useQueryClient()

  const availabilityMutation = useMutation({
    mutationFn: (value: CodeQualityAvailability) =>
      fetchJson(`/enterprises/${enterpriseSlug}/settings/code_quality_policies/update_code_quality_availability`, {
        method: 'PUT',
        body: {code_quality_availability: value},
      }),
    onSuccess: () => queryClient.invalidateQueries({queryKey}),
  })

  const orgMutation = useMutation({
    mutationFn: ({orgId, allowed}: {orgId: number; allowed: boolean}) =>
      fetchJson(`/enterprises/${enterpriseSlug}/settings/code_quality_policies/update_org_code_quality_availability`, {
        method: 'PUT',
        body: {org_id: orgId, allowed},
      }),
    onSuccess: () => queryClient.invalidateQueries({queryKey: ['enterprise-organizations']}),
  })

  const anyError = error || availabilityMutation.error || orgMutation.error
  const anySuccess = isSuccess || availabilityMutation.isSuccess || orgMutation.isSuccess

  return (
    <div>
      <MutationSettledBanner
        mutation={{isSuccess: anySuccess, isError: !!anyError, error: anyError}}
        successMessage="Policy changes saved."
      />

      <div className="Subhead">
        <Heading as="h1" className="Subhead-heading Subhead-heading--large">
          Code Quality
        </Heading>
      </div>

      <div className="tmp-mb-4">
        <Heading as="h2" className="h4 mb-2">
          Organization access
        </Heading>
        <ActionMenu>
          <ActionMenu.Button disabled={availabilityMutation.isPending}>
            {availabilityMutation.isPending && <Spinner size="small" />}
            {AVAILABILITY_OPTIONS.find(o => o.value === codeQualityAvailability)?.label}
          </ActionMenu.Button>
          <ActionMenu.Overlay>
            <ActionList selectionVariant="single">
              {AVAILABILITY_OPTIONS.map(option => (
                <ActionList.Item
                  key={option.value}
                  selected={codeQualityAvailability === option.value}
                  onSelect={() => availabilityMutation.mutate(option.value)}
                >
                  {option.label}
                  <ActionList.Description>{option.description}</ActionList.Description>
                </ActionList.Item>
              ))}
            </ActionList>
          </ActionMenu.Overlay>
        </ActionMenu>

        {codeQualityAvailability === 'selected' && (
          <OrgSelectionList
            enterpriseSlug={enterpriseSlug}
            onOrgToggle={(orgId, allowed) => orgMutation.mutate({orgId, allowed})}
            updatingOrgId={orgMutation.isPending ? orgMutation.variables?.orgId : null}
          />
        )}
      </div>

      <Heading as="h2" className="h4 mb-2">
        Repository admin policy
      </Heading>
      <div className="tmp-mb-4">
        <Heading as="h3" className="h5 text-normal">
          Repository Admins can Enable or Disable GitHub Code Quality.
        </Heading>
        <p className="color-fg-muted tmp-mb-3">
          By allowing this policy, repository admins can choose to enable or disable GitHub Code Quality on
          organization-owned repositories.
        </p>
        <ActionMenu>
          <ActionMenu.Button disabled={isPending}>
            <span>All repositories: </span>
            <span>{isAllowed ? 'Allowed' : 'Not allowed'}</span>
          </ActionMenu.Button>
          <ActionMenu.Overlay>
            <ActionList selectionVariant="single">
              <ActionList.Item selected={isAllowed} onSelect={() => handlePolicyChange(true)}>
                Allowed
                <ActionList.Description>
                  Repository admins can enable or disable GitHub Code Quality.
                </ActionList.Description>
              </ActionList.Item>
              <ActionList.Item selected={!isAllowed} onSelect={() => handlePolicyChange(false)}>
                Not allowed
                <ActionList.Description>
                  Repository admins cannot enable or disable GitHub Code Quality.
                </ActionList.Description>
              </ActionList.Item>
            </ActionList>
          </ActionMenu.Overlay>
        </ActionMenu>
      </div>
    </div>
  )
}
