import {useMutation, type UseMutationResult} from '@github-ui/react-query'
import {
  repoCodeQualitySettingsRoute,
  type RepoCodeQualitySettingsResponse,
} from '../routes/repo-code-quality-settings-route'
import {fetchJson} from '../utils/fetch-json'

interface UpdateSettingsParams {
  owner: string
  repo: string
  languages: string[]
  runnerLabel: string | null
  runnerType: string | null
}

export function useUpdateCodeQualitySettingsMutation(): UseMutationResult<
  RepoCodeQualitySettingsResponse,
  Error,
  UpdateSettingsParams
> {
  return useMutation({
    mutationFn: async (params: UpdateSettingsParams) => {
      const response = await fetchJson<RepoCodeQualitySettingsResponse>(
        repoCodeQualitySettingsRoute.generatePath({owner: params.owner, repo: params.repo}),
        {
          method: 'POST',
          body: {
            config: {
              languages: params.languages,
              runner_label: params.runnerLabel,
              runner_type: params.runnerType,
            },
          },
        },
      )
      return response
    },
  })
}
