import {
  CreateBranchDialog,
  type OnCreateBranchData,
  type OnCreateBranchOptions,
} from '@github-ui/code-scanning-shared/components/CreateBranchDialog'
import {useCallback, useMemo} from 'react'
import type {Repository} from '@github-ui/code-scanning-shared/types/repository'
import type {SuggestedFixFile} from '../types/suggested-fix'
import {useRecentActivityCommitFixMutation} from '../hooks/use-recent-activity-commit-fix-mutation'
import {codeQualityAIFindingsFixCommitPath} from '@github-ui/paths'
import type {RecentActivityFix} from '../types/recent-activity-commit-fix-request'

export interface RecentActivityCommitFixDialogProps {
  suggestedFixFiles: SuggestedFixFile[]
  owner: string
  repo: string
  defaultBranch: string
  branchListCacheKey: string
  onClose: () => void
}

export function RecentActivityCommitFixDialog({
  suggestedFixFiles,
  owner,
  repo,
  defaultBranch,
  branchListCacheKey,
  onClose,
}: RecentActivityCommitFixDialogProps) {
  const filePath = suggestedFixFiles[0]?.filePath ?? 'file'

  const {
    isPending,
    error,
    mutate,
    data: mutationResponse,
  } = useRecentActivityCommitFixMutation(
    codeQualityAIFindingsFixCommitPath({
      owner,
      repo,
    }),
  )

  const onCreateBranch = useCallback(
    (data: OnCreateBranchData, {onSuccess}: OnCreateBranchOptions) => {
      const suggestedFixes: RecentActivityFix[] = suggestedFixFiles.map(file => ({
        filePath: file.filePath,
        diffContent: file.diff,
      }))

      mutate(
        {
          fixes: suggestedFixes,
          name: data.branchName,
          createNewBranch: data.createNewBranch,
          createDraftPR: data.createPullRequest,
        },
        {
          onSuccess: response => {
            onSuccess({
              branchName: response.branchName,
              pullRequest: response.pullRequest,
              errorMessages: response.messages,
            })
          },
        },
      )
    },
    [mutate, suggestedFixFiles],
  )

  const repository = useMemo(
    (): Repository => ({
      ownerLogin: owner,
      name: repo,
      defaultBranch,
    }),
    [owner, repo, defaultBranch],
  )

  return (
    <CreateBranchDialog
      repository={repository}
      branchListCacheKey={branchListCacheKey}
      branchType="new"
      dialogTitle="Commit autofixes to new branch"
      submitButtonContent="Commit change"
      showCommitMessageField={false}
      showPullRequestNextStep
      initialNextStep="pr"
      initialBranchName={`ai-findings-autofix/${filePath.replaceAll('/', '-')}`}
      initialCommitMessage={`Fixes for ${filePath}`}
      onCancel={onClose}
      onClose={onClose}
      onCreateBranch={onCreateBranch}
      isPending={isPending}
      error={error}
      createdPullRequest={mutationResponse?.pullRequest}
    />
  )
}
