export const Grade = {
  A: 'A',
  B: 'B',
  C: 'C',
  D: 'D',
} as const

export type Grade = (typeof Grade)[keyof typeof Grade]

export const gradeToText = {
  [Grade.A]: 'Excellent',
  [Grade.B]: 'Good',
  [Grade.C]: 'Fair',
  [Grade.D]: 'Needs Improvement',
}

export const gradeToFilterValue = {
  [Grade.A]: 'excellent',
  [Grade.B]: 'good',
  [Grade.C]: 'fair',
  [Grade.D]: 'needs-improvement',
}

// gradeToNumber is a mapping from each grade to its x/y position on the graph. Higher is better.
export const gradeToNumber: Record<Grade, number> = {
  [Grade.A]: 3,
  [Grade.B]: 2,
  [Grade.C]: 1,
  [Grade.D]: 0,
}

export const gradeToColor: Record<Grade, string> = {
  [Grade.A]: 'success',
  [Grade.B]: 'attention',
  [Grade.C]: 'severe',
  [Grade.D]: 'danger',
}
