import {useMemo} from 'react'
import {useSyncedState} from '@primer/react'
import {orgCodeQualityOptionsPath} from '@github-ui/paths'
import {Filter, type FilterQuery} from '@github-ui/filter'
import {
  TeamFilterProvider,
  TopicFilterProvider,
  CustomPropertyFilterProvider,
} from '@github-ui/code-scanning-shared/filter-providers/repository-filter-providers'
import {useFilterParams} from '../hooks/use-filter-params'
import {
  AiFindingsFilterProvider,
  MaintainabilityScoreFilterProvider,
  ReliabilityScoreFilterProvider,
  SortFilterProvider,
  StandardFindingsFilterProvider,
  VisibilityFilterProvider,
} from '../filter-providers/org-static-providers'

export type OrgFilterProps = {
  organizationLogin: string
  customPropertyNames: string[]
}

export function OrgFilter({organizationLogin, customPropertyNames}: OrgFilterProps) {
  const filterProviders = useMemo(
    () => [
      new ReliabilityScoreFilterProvider({
        priority: 1,
      }),
      new MaintainabilityScoreFilterProvider({
        priority: 1,
      }),
      new StandardFindingsFilterProvider({
        priority: 1,
      }),
      new AiFindingsFilterProvider({
        priority: 1,
      }),
      new TopicFilterProvider(
        {
          path: orgCodeQualityOptionsPath({org: organizationLogin, optionsType: 'topics'}),
        },
        {
          priority: 2,
        },
      ),
      new TeamFilterProvider(
        {
          path: orgCodeQualityOptionsPath({org: organizationLogin, optionsType: 'teams'}),
        },
        {
          priority: 2,
        },
      ),
      new VisibilityFilterProvider({
        priority: 2,
      }),
      ...customPropertyNames.map(
        name =>
          new CustomPropertyFilterProvider(
            {
              customPropertyName: name,
              path: orgCodeQualityOptionsPath({org: organizationLogin, optionsType: 'props', name}),
            },
            {
              priority: 3,
            },
          ),
      ),
      new SortFilterProvider(),
    ],
    [organizationLogin, customPropertyNames],
  )

  const {query, onQueryChange} = useFilterParams()
  const handleSubmit = (request: FilterQuery) => {
    onQueryChange(request.raw)
  }

  const [filterValue, setFilterValue] = useSyncedState(query)

  return (
    <Filter
      className="mt-2 tmp-mb-4"
      id="code-quality-org-filter"
      label="Filter"
      placeholder="Filter"
      // Setting variant to "input" disables the advanced filter dialog to work around a bug with "has" filters.
      // See https://github.com/github/code-scanning/issues/21776
      variant="input"
      providers={filterProviders}
      filterValue={filterValue}
      onChange={setFilterValue}
      onSubmit={handleSubmit}
    />
  )
}
