import {Filter, type FilterQuery} from '@github-ui/filter'
import {useMemo} from 'react'
import {useSyncedState} from '@primer/react'

import {StateFilterProvider} from '../filter-providers/repo-static-providers'

export interface RuleFindingsFilterProps {
  query: string
  onQueryChange: (query: string) => void
}

export function RuleFindingsFilter({query, onQueryChange}: RuleFindingsFilterProps) {
  const [filterValue, setFilterValue] = useSyncedState(query)

  const providers = useMemo(() => [new StateFilterProvider()], [])

  const handleSubmit = (request: FilterQuery) => {
    onQueryChange(request.raw)
  }

  return (
    <Filter
      id="rule-findings-filter"
      label="Filter findings"
      providers={providers}
      filterValue={filterValue}
      onChange={setFilterValue}
      onSubmit={handleSubmit}
    />
  )
}
