import {mainQuery} from '@github-ui/react-core/future/main-query'
import {codeQualityAppBuilder} from '../config/app-builder'

export type OrgCodeQualitySettingsResponse = {
  org: string
  orgName: string
  enabled: boolean
  repoCount: number
}

export const orgCodeQualitySettingsRoute = codeQualityAppBuilder.createQueryRouteConfig('orgCodeQualitySettingsRoute', {
  path: '/organizations/:org/settings/code-quality',
  queries: [mainQuery<OrgCodeQualitySettingsResponse>()],
})
