import {Banner} from '@primer/react'

interface MutationSettledBannerProps {
  mutation: {
    isSuccess: boolean
    isError: boolean
    error: Error | null
  }
  successMessage?: string
}

export function MutationSettledBanner({mutation, successMessage = 'Changes saved.'}: MutationSettledBannerProps) {
  return (
    <>
      {mutation.isSuccess && <Banner title={successMessage} variant="info" className="tmp-mb-3" />}
      {mutation.isError && mutation.error && (
        <Banner title={mutation.error.message} variant="critical" className="tmp-mb-3" />
      )}
    </>
  )
}
