import {useQuery, type UseQueryResult} from '@github-ui/react-query'
import {fetchJson} from '../utils/fetch-json'

export interface Organization {
  id: number
  login: string
  avatar_url: string
  allowed: boolean
}

interface EnterpriseOrganizationsResponse {
  organizations: Organization[]
  total_count: number
  page: number
  per_page: number
  total_pages: number
}

interface UseEnterpriseOrganizationsParams {
  enterpriseSlug: string
  page?: number
  query?: string
}

export function useEnterpriseOrganizations({
  enterpriseSlug,
  page = 1,
  query = '',
}: UseEnterpriseOrganizationsParams): UseQueryResult<EnterpriseOrganizationsResponse> {
  return useQuery({
    queryKey: ['enterprise-organizations', enterpriseSlug, page, query],
    queryFn: async () => {
      const searchParams = new URLSearchParams()
      searchParams.set('page', String(page))
      if (query) {
        searchParams.set('query', query)
      }

      return fetchJson<EnterpriseOrganizationsResponse>(
        `/enterprises/${enterpriseSlug}/settings/code_quality_policies/organizations?${searchParams.toString()}`,
      )
    },
    staleTime: 30000, // 30 seconds
  })
}
