import {AlertIcon, CircleSlashIcon, NoteIcon, XIcon} from '@primer/octicons-react'
import styles from './FindingSeverityBadge.module.css'

export type FindingSeverityBadgeProps = {
  severity: FindingSeverity
}

export const FindingSeverity = {
  None: 'none',
  Error: 'error',
  Warning: 'warning',
  Note: 'note',
  Nit: 'nit',
  Low: 'low',
  Medium: 'medium',
  High: 'high',
  Critical: 'critical',
  Failure: 'failure',
  Notice: 'notice',
} as const

export type FindingSeverity = (typeof FindingSeverity)[keyof typeof FindingSeverity]

export function FindingSeverityBadge({severity}: FindingSeverityBadgeProps) {
  switch (severity) {
    case FindingSeverity.Note:
      return (
        <span className={`${styles.severityBadge} ${styles.severityNote}`}>
          <NoteIcon className="color-fg-default pr-1 margin-top-2" />
          Note
        </span>
      )
    case FindingSeverity.Warning:
      return (
        <span className={`${styles.severityBadge} ${styles.severityWarning}`}>
          <AlertIcon className="color-fg-attention pr-1" />
          Warning
        </span>
      )
    case FindingSeverity.Error:
      return (
        <span className={`${styles.severityBadge} ${styles.severityError}`}>
          <CircleSlashIcon className="color-fg-danger pr-1" />
          Error
        </span>
      )
    case FindingSeverity.Nit:
      return (
        <span className={`${styles.severityBadge} ${styles.severityNote}`}>
          <NoteIcon className="color-fg-default pr-1" />
          Nit
        </span>
      )
    case FindingSeverity.Low:
      return (
        <span className={`${styles.severityBadge} ${styles.severityNote}`}>
          <NoteIcon className="color-fg-default pr-1" />
          Low
        </span>
      )
    case FindingSeverity.Medium:
      return (
        <span className={`${styles.severityBadge} ${styles.severityWarning}`}>
          <AlertIcon className="color-fg-attention pr-1" />
          Medium
        </span>
      )
    case FindingSeverity.High:
      return (
        <span className={`${styles.severityBadge} ${styles.severityError}`}>
          <CircleSlashIcon className="color-fg-danger pr-1" />
          High
        </span>
      )
    case FindingSeverity.Critical:
      return (
        <span className={`${styles.severityBadge} ${styles.severityError}`}>
          <CircleSlashIcon className="color-fg-danger pr-1" />
          Critical
        </span>
      )
    case FindingSeverity.Failure:
      return (
        <span className={`${styles.severityBadge} ${styles.severityError}`}>
          <XIcon className="color-fg-danger pr-1" />
          Failure
        </span>
      )
    case FindingSeverity.Notice:
      return (
        <span className={`${styles.severityBadge} ${styles.severityNote}`}>
          <NoteIcon className="color-fg-default pr-1 margin-top-2" />
          Notice
        </span>
      )
    default:
      return null
  }
}
