export type RuleSortField = 'alpha' | 'count' | 'severity'

export type RuleSortDirection = 'asc' | 'desc'

export function isSortField(value: string): value is RuleSortField {
  return (SORT_FIELDS as readonly string[]).includes(value)
}

export function isSortDirection(value: string): value is RuleSortDirection {
  return (SORT_DIRECTIONS as readonly string[]).includes(value)
}

export const SORT_FIELD_LABELS: Record<RuleSortField, string> = {
  alpha: 'Alphabetically',
  count: 'Number of findings',
  severity: 'Severity',
}

export const SORT_FIELDS = Object.keys(SORT_FIELD_LABELS) as RuleSortField[]

export const SORT_DIRECTIONS: readonly RuleSortDirection[] = ['asc', 'desc'] as const

export const DEFAULT_SORT_FIELD: RuleSortField = 'count'
export const DEFAULT_SORT_DIRECTION: RuleSortDirection = 'desc'
