export class LanguageFilterProvider extends SelectFilterProvider {
  constructor(options?: SuppliedFilterProviderOptions) {
    super(
      {
        key: 'language',
        displayName: 'Language',
        description: 'Filter by language',
        priority: 1,
        icon: CodeIcon,
      },
      [
        {
          value: RuleLanguage.CSharp,
          displayName: RuleLanguageFilterOption.CSharp,
          priority: 1,
          iconColor: getLanguageColor(RuleLanguage.CSharp),
        },
        {
          value: RuleLanguage.Go,
          displayName: RuleLanguageFilterOption.Go,
          priority: 2,
          iconColor: getLanguageColor(RuleLanguage.Go),
        },
        {
          value: RuleLanguage.Java,
          displayName: RuleLanguageFilterOption.Java,
          priority: 3,
          iconColor: getLanguageColor(RuleLanguage.Java),
        },
        {
          value: RuleLanguage.JavaScript,
          displayName: RuleLanguageFilterOption.JavaScript,
          priority: 4,
          iconColor: getLanguageColor(RuleLanguage.JavaScript),
        },
        {
          value: RuleLanguage.Python,
          displayName: RuleLanguageFilterOption.Python,
          priority: 5,
          iconColor: getLanguageColor(RuleLanguage.Python),
        },
        {
          value: RuleLanguage.Ruby,
          displayName: RuleLanguageFilterOption.Ruby,
          priority: 6,
          iconColor: getLanguageColor(RuleLanguage.Ruby),
        },
      ],
      {
        ...options,
        filterTypes: {
          ...DEFAULT_FILTER_TYPE_OPTIONS,
          exclusive: false,
          ...options?.filterTypes,
        },
      },
    )
  }
}
