import DataCard from '@github-ui/data-card'
import {Grade, gradeToText} from '../types/grade'
import type {CodeQualityDocsUrls} from '../types/code-quality-docs-urls'
import {Link} from '@primer/react'
import styles from './Metric.module.css'
import {MetricProgressBar} from './MetricProgressBar'

export interface MetricProps {
  title: string
  data?: {
    grade: Grade
    findingsCount: number
  }
  codeQualityDocsUrls: CodeQualityDocsUrls
}

export function Metric({title, data, codeQualityDocsUrls}: MetricProps) {
  const findingsCount = data?.findingsCount || 0

  return (
    <DataCard className={styles.DataCard}>
      <h3 className={styles.CustomHeading}>{title}</h3>
      <p className={styles.GradeText}>{data ? gradeToText[data.grade] : 'No data'}</p>
      <MetricProgressBar grade={data ? data.grade : undefined} />
      <DataCard.Description className={styles.CustomDescription}>
        <span>
          {findingsCount} findings.
          {data && (
            <>
              {' '}
              <Link href={codeQualityDocsUrls.metrics} target="_blank" inline>
                Learn how this score is calculated.
              </Link>
            </>
          )}
        </span>
      </DataCard.Description>
    </DataCard>
  )
}
