import {EmptyCell} from './EmptyCell'
import {CodeDiffLine} from './CodeDiffLine'
import type {SuggestedFixDiffLine} from '../../types/suggested-fix'

interface DiffSideProps {
  diffLine: SuggestedFixDiffLine | null
  hasHiddenUnicodeCharacters: boolean
  isLeftSide?: boolean
}

export const DiffLineSide = ({diffLine, hasHiddenUnicodeCharacters, isLeftSide}: DiffSideProps) => {
  if (diffLine === null) {
    return (
      <>
        <EmptyCell isLeftSide={isLeftSide} />
        <EmptyCell isLeftSide={isLeftSide} />
      </>
    )
  }

  switch (diffLine.type) {
    case 'HUNK':
      return null
    case 'ADDITION':
    case 'DELETION':
    case 'CONTEXT':
    case 'INJECTED_CONTEXT':
      return (
        <CodeDiffLine
          diffLine={diffLine}
          hasHiddenUnicodeCharacters={hasHiddenUnicodeCharacters}
          isLeftSide={isLeftSide}
        />
      )
    default:
      throw new Error(`cannot handle type ${diffLine.type}`)
  }
}
