import {useMutation, type UseMutationResult} from '@github-ui/react-query'
import {
  orgCodeQualitySettingsRoute,
  type OrgCodeQualitySettingsResponse,
} from '../routes/org-code-quality-settings-route'
import {fetchJson} from '../utils/fetch-json'

interface ToggleOrgCodeQualityParams {
  org: string
  enabled: boolean
}

export function useToggleOrgCodeQualityOnReposMutation(): UseMutationResult<
  OrgCodeQualitySettingsResponse,
  Error,
  ToggleOrgCodeQualityParams
> {
  return useMutation({
    mutationFn: async (params: ToggleOrgCodeQualityParams) => {
      const response = await fetchJson<OrgCodeQualitySettingsResponse>(
        orgCodeQualitySettingsRoute.generatePath({org: params.org}),
        {
          method: 'PATCH',
          body: {enabled: params.enabled},
        },
      )
      return response
    },
  })
}
