import type {SafeHTMLString} from '@github-ui/safe-html'
import type {SuggestedFix} from './suggested-fix'

export type RuleFinding = {
  number: number
  filePath: string
  startLine: number
  endLine: number
  startColumn: number
  endColumn: number
  snippetStartLine: number
  codeSnippetLines: SafeHTMLString[]
  suggestedFix?: SuggestedFix
  findingState: FindingState
  message?: SafeHTMLString
}

export const FindingState = {
  Open: 'open',
  Dismissed: 'dismissed',
}

export type FindingState = (typeof FindingState)[keyof typeof FindingState]

export const FindingStateFilterOption = {
  Open: 'Open',
  Dismissed: 'Dismissed',
} as const

export type FindingStateFilterOption = (typeof FindingStateFilterOption)[keyof typeof FindingStateFilterOption]

export const DEFAULT_FINDING_STATE = FindingState.Open
