import {ConfirmationDialog, Link} from '@primer/react'

export type EnableCodeQualityConfirmationDialogProps = {
  repoCount: number
  onClose: (gesture: 'confirm' | 'cancel' | 'close-button' | 'escape') => void
}

export function EnableCodeQualityConfirmationDialog({repoCount, onClose}: EnableCodeQualityConfirmationDialogProps) {
  return (
    <ConfirmationDialog
      title="Enable Code Quality"
      onClose={onClose}
      width="xlarge"
      height="auto"
      confirmButtonContent="Confirm"
      cancelButtonContent="Cancel"
      confirmButtonType="primary"
    >
      <p className="mb-2">
        Turning this on across{' '}
        <strong>
          {repoCount} {repoCount === 1 ? <span>repository</span> : <span>repositories</span>}
        </strong>{' '}
        in this organization will incur additional costs beginning July 20, 2026:
      </p>
      <ul className="pl-4">
        <li>License costs per active committer</li>
        <li>Additional AI usage-based costs and Actions minutes</li>
      </ul>
      <p className="mt-2">
        For more information, refer to the{' '}
        <Link
          href="https://docs.github.com/en/billing/concepts/product-billing/github-code-quality"
          inline
          target="_blank"
        >
          Code Quality documentation
        </Link>
        .
      </p>
    </ConfirmationDialog>
  )
}
