import {PrevNextPagination} from '@github-ui/code-scanning-shared/components/PrevNextPagination'
import {useFilterParams} from '../hooks/use-filter-params'

export type OrgReposPaginationProps = {
  prevCursor: string | null | undefined
  nextCursor: string | null | undefined
}

export function OrgReposPagination({prevCursor, nextCursor}: OrgReposPaginationProps) {
  const {onCursorChange} = useFilterParams()

  return (
    <PrevNextPagination
      prevCursor={prevCursor}
      nextCursor={nextCursor}
      onCursorChange={onCursorChange}
      className="mt-1"
    />
  )
}
